import React from "react";
import { Navbar as RBNavbar, Container, Button } from "react-bootstrap";
import { logout } from "../utils/auth";
import NotificationCenter from "./NotificationCenter";

function Navbar() {
  return (
    <RBNavbar
      variant="dark"
      expand="lg"
      sticky="top"
      className="nb-brand-gradient shadow-sm"
      style={{ zIndex: 1030 }}
    >
      <Container fluid className="px-4">

        <RBNavbar.Brand href="/" className="d-flex align-items-center gap-2 fw-bold fs-5">
          <span
            className="d-flex align-items-center justify-content-center rounded-3 bg-white"
            style={{ width: "32px", height: "32px" }}
          >
            <i className="bi bi-bank2 text-primary" style={{ fontSize: "16px" }}></i>
          </span>
          <span>
            Nexa<span style={{ color: "var(--nb-accent)" }}>Bank</span>
            <span className="fw-light ms-1 text-white-50" style={{ fontSize: "13px" }}>Digital Banking</span>
          </span>
        </RBNavbar.Brand>

        <div className="d-flex align-items-center gap-3 ms-auto">
          <NotificationCenter />
          <Button
            variant="light"
            size="sm"
            className="fw-semibold rounded-pill px-3"
            onClick={logout}
          >
            <i className="bi bi-box-arrow-right me-1"></i>
            Logout
          </Button>
        </div>

      </Container>
    </RBNavbar>
  );
}

export default Navbar;
